    await fs.mkdir(contentDir, { recursive: true });
    await fs.writeFile(
      path.join(contentDir, "page.md"),
      `---
title: Page
---

# Page
`
    );

    const port = getPort();
    const { server, wss } = await startDevServer({
      contentDir,
      outputDir,
      port,
    });

    servers.push({
      close: async () => {
        wss.close();
        await new Promise<void>((resolve) => server.close(() => resolve()));
      },
    });

    await fs.writeFile(
      path.join(outputDir, "style.css"),
      "body { color: red; }",
      "utf-8"
    );

